-- Errata reading for M36: Same-day visit included (0..N days after the plan).
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('discharge_plans','encounters')), dp AS (SELECT patient, json_extract(payload,'$.record_id') rid, json_extract(payload,'$.event_date') d, json_extract(payload,'$.recommended_within_days') n FROM r WHERE stream='discharge_plans' AND json_extract(payload,'$.recommended_within_days') IS NOT NULL), v AS (SELECT patient, json_extract(payload,'$.encounter_id') eid, min(json_extract(payload,'$.event_date')) d FROM r WHERE stream='encounters' AND json_extract(payload,'$.type') IN ('office','primary_care','pediatric_office','specialist_office','specialty_followup') AND json_extract(payload,'$.status')='completed' GROUP BY 1,2), hit AS (SELECT DISTINCT dp.rid FROM dp JOIN v ON v.patient=dp.patient AND julianday(v.d)-julianday(dp.d) BETWEEN 0 AND dp.n) SELECT ROUND(100.0*(SELECT COUNT(*) FROM hit)/(SELECT COUNT(*) FROM dp),1) AS value;
